<PageTitle>Dispatcher Dashboard</PageTitle>

<h2>Dispatcher Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <input class="form-control" placeholder="Filter by tracking #, destination, or recipient…"
               @bind="filterText" @bind:event="oninput" />
